"use client";
import type { RefObject } from "react";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisNavbarContent } from "./components/navbar/content";
import View3 from "./components/navbar/variants/04-feature-morph";
const variants = {"feature-morph":View3};
export type { ArtemisNavbarColumn, ArtemisNavbarContent, ArtemisNavbarLink, ArtemisNavbarMenu, ArtemisNavbarMenuLink } from "./components/navbar/content";
export interface ArtemisNavbarProps { className?: string; scrollContainer?: RefObject<HTMLElement | null>; variant?: "feature-morph"; /** The words on the navbar; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisNavbarContent>; }
export function ArtemisNavbar({ className, variant = "feature-morph", content }: ArtemisNavbarProps) {const View = variants[variant];return <ArtemisScope className={`art:relative art:z-40 ${className ?? ""}`}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisNavbarLink {
  label: string;
  href: string;
}

/** A link inside an open menu. */
export interface ArtemisNavbarMenuLink extends ArtemisNavbarLink {
  /** A short line under the label. morph and feature-morph. */
  description?: string;
  /** The card's icon. feature-morph, which keeps its own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** A small heading over a list of links, inside an open menu. */
export interface ArtemisNavbarColumn {
  title: string;
  links: ArtemisNavbarLink[];
}

/** A top-level item that opens a menu. */
export interface ArtemisNavbarMenu {
  label: string;
  /** Headed columns of links. pill-groups and mega-menu; morph and feature-morph list their links. */
  columns?: ArtemisNavbarColumn[];
  /** Links, each with an optional description and icon. morph and feature-morph; pill-groups and mega-menu show them as one column when `columns` is left out. feature-morph sets them in a fixed two-by-two panel, so four fill it. */
  links?: ArtemisNavbarMenuLink[];
  /** A highlighted card beside the columns. mega-menu. */
  feature?: { title: string; description: string; href: string };
}

/** The words on an Artemis navbar. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisNavbarContent {
  /** The name beside the logo mark, and where it links. All layouts. */
  brand: ArtemisNavbarLink;
  /** Items that open a menu, shown before `links`. pill-groups, mega-menu, morph and feature-morph. */
  menus?: ArtemisNavbarMenu[];
  /** Plain links in the bar. All layouts. The bars of morph and feature-morph have a fixed width: their own two one-word menus and two links fill them, and more or longer labels wrap or overflow. */
  links: ArtemisNavbarLink[];
  /** The quiet sign-in link. pill-groups, mega-menu, morph and feature-morph. */
  login?: ArtemisNavbarLink;
  /** A sign-up link beside sign-in. pill-groups. */
  signup?: ArtemisNavbarLink;
  /** The main button. All layouts. */
  cta: ArtemisNavbarLink;
  /** A line at the foot of an open menu, beside a link to `cta`. pill-groups and mega-menu. */
  menuNote?: string;
}

"use client";
// @zeus-internal
import { useCallback, useEffect, useId, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { Panel, defaultMenus } from "./04-feature-morph/panel";
import type { ArtemisNavbarContent } from "../content";
const DEFAULT = {
    brand: { label: "Workspace", href: "/" },
    menus: defaultMenus,
    links: [{ label: "Pricing", href: "#pricing" }, { label: "Stories", href: "#stories" }],
    login: { label: "Log in", href: "#log-in" },
    cta: { label: "Start free", href: "#start-free" },
} satisfies ArtemisNavbarContent;
export default function NavbarFeatureMorph({ content }: { content?: Partial<ArtemisNavbarContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const id = useId();
    const reduced = !!useReducedMotion();
    const nav = useRef<HTMLElement>(null);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const [open, setOpen] = useState(false);
    const [mobile, setMobile] = useState(false);
    const [group, setGroup] = useState(0);
    const [direction, setDirection] = useState(0);
    const cancel = useCallback(() => { if (timer.current)
        clearTimeout(timer.current); timer.current = null; }, []);
    const close = useCallback(() => { cancel(); setOpen(false); setMobile(false); }, [cancel]);
    const choose = (value: number, desktop = false) => {
        cancel();
        if (value !== group)
            setDirection(open || mobile ? value > group ? 1 : -1 : 0);
        else if (!open && !mobile)
            setDirection(0);
        setGroup(value);
        if (desktop)
            setOpen(true);
    };
    useEffect(() => {
        const outside = (event: PointerEvent) => { if (event.target instanceof Node && !nav.current?.contains(event.target))
            close(); };
        const escape = (event: KeyboardEvent) => { if (event.key === "Escape")
            close(); };
        document.addEventListener("pointerdown", outside);
        document.addEventListener("keydown", escape);
        return () => { document.removeEventListener("pointerdown", outside); document.removeEventListener("keydown", escape); cancel(); };
    }, [cancel, close]);
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    const spring = reduced ? { duration: 0 } : ARTEMIS_SPRING_PANEL;
    return <header className="art:h-[4.125rem] art:w-full">
          <nav ref={nav} onMouseEnter={cancel} onMouseLeave={() => { if (!mobile) {
        cancel();
        timer.current = setTimeout(() => setOpen(false), 100);
    } }} aria-label="Primary navigation" className="art:relative art:mx-auto art:h-[4.125rem] art:w-full art:max-w-[45rem]">
            <svg aria-hidden="true" viewBox="0 0 720 414" preserveAspectRatio="none" className="art:pointer-events-none art:absolute art:inset-x-0 art:top-0 art:z-0 art:w-full art:hidden art:h-[25.875rem] art:@min-[768px]/artemis:block">
              <motion.path initial={false} animate={{ d: open ? "M 33 0 H 687 Q 720 0 720 33 V 384 Q 720 414 690 414 H 30 Q 0 414 0 384 V 33 Q 0 0 33 0 Z" : "M 33 0 H 687 Q 720 0 720 33 V 33 Q 720 66 687 66 H 33 Q 0 66 0 33 V 33 Q 0 0 33 0 Z" }} transition={spring} fill="var(--artemis-muted)" fillOpacity="0.8" stroke="var(--artemis-border)" strokeOpacity="0.6" strokeWidth="1" vectorEffect="non-scaling-stroke"/>
            </svg>
            <svg aria-hidden="true" viewBox="0 0 360 500" preserveAspectRatio="none" className="art:pointer-events-none art:absolute art:inset-x-0 art:top-0 art:z-0 art:w-full art:h-[31.25rem] art:@min-[768px]/artemis:hidden">
              <motion.path initial={false} animate={{ d: mobile ? "M 33 0 H 327 Q 360 0 360 33 V 470 Q 360 500 330 500 H 30 Q 0 500 0 470 V 33 Q 0 0 33 0 Z" : "M 33 0 H 327 Q 360 0 360 33 V 33 Q 360 66 327 66 H 33 Q 0 66 0 33 V 33 Q 0 0 33 0 Z" }} transition={spring} fill="var(--artemis-muted)" fillOpacity="0.8" stroke="var(--artemis-border)" strokeOpacity="0.6" strokeWidth="1" vectorEffect="non-scaling-stroke"/>
            </svg>
            <div className="art:relative art:z-30 art:flex art:h-[4.125rem] art:items-center art:gap-0.5 art:p-2 art:px-3 art:@min-[640px]/artemis:px-4">
              <a href={copy.brand.href} aria-label={copy.brand.label} className="art:mr-auto art:flex art:h-10 art:shrink-0 art:items-center art:gap-2 art:rounded-full art:px-1.5 art:pr-2.5 art:font-semibold art:text-foreground art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-foreground/30">
                <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-primary art:text-primary-foreground">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-orbit art:size-4.5" aria-hidden="true">
                    <path d="M20.341 6.484A10 10 0 0 1 10.266 21.85"/>
                    <path d="M3.659 17.516A10 10 0 0 1 13.74 2.152"/>
                    <circle cx="12" cy="12" r="3"/>
                    <circle cx="19" cy="5" r="2"/>
                    <circle cx="5" cy="19" r="2"/>
                  </svg>
                </span>
                <span className="art:hidden art:@min-[640px]/artemis:inline">
                  {copy.brand.label}
                </span>
              </a>
              <div className="art:hidden art:shrink-0 art:items-center art:gap-0.5 art:@min-[768px]/artemis:flex">
                {copy.menus.map((menu, value) => <motion.button {...press} key={menu.label} onMouseEnter={() => choose(value, true)} onClick={() => choose(value, true)} type="button" className={`art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:hover:bg-transparent art:flex art:h-10 art:items-center art:gap-1 art:px-2.5 art:font-medium art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-foreground/30 ${open && group === value ? "art:hover:text-inherit art:bg-muted art:text-foreground" : "art:text-muted-foreground art:hover:text-foreground"} art:rounded-full`} aria-expanded={open && group === value} aria-controls={id} aria-haspopup="true" tabIndex={0}>
                  {menu.label}
                  <motion.span aria-hidden="true" animate={{ rotate: open && group === value ? 180 : 0 }} transition={spring}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-down art:size-3.5" aria-hidden="true">
                      <path d="m6 9 6 6 6-6"/>
                    </svg>
                  </motion.span>
                </motion.button>)}
                {copy.links.map(link => <a key={link.label} onMouseEnter={close} onClick={close} href={link.href} className="art:flex art:h-10 art:items-center art:rounded-full art:px-2.5 art:font-medium art:text-muted-foreground art:text-sm art:outline-none art:transition-colors art:hover:text-foreground art:focus-visible:ring-2 art:focus-visible:ring-foreground/30">
                  {link.label}
                </a>)}
              </div>
              <div className="art:ml-auto art:hidden art:shrink-0 art:items-center art:gap-0.5 art:@min-[768px]/artemis:flex">
                <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:h-8 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:rounded-full" href={copy.login.href} tabIndex={0}>
                  {copy.login.label}
                </motion.a>
                <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:h-8 art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:rounded-full" href={copy.cta.href} tabIndex={0}>
                  {copy.cta.label}
                </motion.a>
              </div>
              <motion.button {...press} onClick={() => { cancel(); setOpen(false); setDirection(0); setMobile(!mobile); }} type="button" className="art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:p-0 art:font-normal art:hover:text-inherit art:relative art:grid art:size-10 art:place-items-center art:text-foreground art:outline-none art:transition-colors art:hover:bg-muted art:focus-visible:ring-2 art:focus-visible:ring-foreground/30 art:@min-[768px]/artemis:hidden art:rounded-full" aria-label={mobile ? "Close menu" : "Open menu"} aria-expanded={mobile} aria-controls={`${id}-mobile`} tabIndex={0}>
                <motion.span initial={{}} animate={{ scale: mobile ? 0.25 : 1, opacity: mobile ? 0 : 1, filter: mobile ? "blur(4px)" : "blur(0px)" }} transition={spring}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-menu art:size-5" aria-hidden="true">
                    <path d="M4 5h16"/>
                    <path d="M4 12h16"/>
                    <path d="M4 19h16"/>
                  </svg>
                </motion.span>
                <motion.span className="art:absolute" initial={{}} animate={{ scale: mobile ? 1 : 0.25, opacity: mobile ? 1 : 0, filter: mobile ? "blur(0px)" : "blur(4px)" }} transition={spring}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-5" aria-hidden="true">
                    <path d="M18 6 6 18"/>
                    <path d="m6 6 12 12"/>
                  </svg>
                </motion.span>
              </motion.button>
            </div>
            <AnimatePresence>{open && <Panel key="desktop" id={id} mobile={false} menus={copy.menus} links={copy.links} login={copy.login} cta={copy.cta} group={group} direction={direction} reduced={reduced} choose={choose} close={close}/>}</AnimatePresence>
            <AnimatePresence>{mobile && <Panel key="mobile" id={id} mobile menus={copy.menus} links={copy.links} login={copy.login} cta={copy.cta} group={group} direction={direction} reduced={reduced} choose={choose} close={close}/>}</AnimatePresence>
          </nav>
        </header>;
}

"use client";
// @zeus-internal
import { AnimatePresence, motion } from "motion/react";
import { Activity, BookOpen, LayoutTemplate, MessagesSquare, Orbit, ScanLine, Waypoints, Workflow } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
import type { ArtemisNavbarLink, ArtemisNavbarMenu, ArtemisNavbarMenuLink } from "../../content";
export const defaultMenus: ArtemisNavbarMenu[] = [
    { label: "Platform", links: [
        { label: "Automations", description: "Build flows that run themselves", href: "#automations", icon: Workflow },
        { label: "Liveboards", description: "Watch every signal as it arrives", href: "#liveboards", icon: ScanLine },
        { label: "Journeys", description: "Map each step across your product", href: "#journeys", icon: Waypoints },
        { label: "Templates", description: "Start with a proven workflow", href: "#templates", icon: LayoutTemplate },
    ] },
    { label: "Resources", links: [
        { label: "Field notes", description: "Practical guides from the team", href: "#field-notes", icon: BookOpen },
        { label: "Community", description: "Learn alongside other builders", href: "#community", icon: MessagesSquare },
        { label: "System status", description: "Live service health and history", href: "#status", icon: Activity },
        { label: "Quickstarts", description: "Ship your first flow in minutes", href: "#quickstarts", icon: Orbit },
    ] },
];
/** The default icons in order, for cards that come without one. */
const icons = [Workflow, ScanLine, Waypoints, LayoutTemplate, BookOpen, MessagesSquare, Activity, Orbit];
export function Panel({ id, mobile, menus, links, login, cta, group, direction, reduced, choose, close }: {
    id: string;
    mobile: boolean;
    menus: ArtemisNavbarMenu[];
    links: ArtemisNavbarLink[];
    login: ArtemisNavbarLink;
    cta: ArtemisNavbarLink;
    group: number;
    direction: number;
    reduced: boolean;
    choose: (group: number) => void;
    close: () => void;
}) {
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    const menu = menus[group];
    const cards: ArtemisNavbarMenuLink[] = menu?.links ?? menu?.columns?.flatMap(column => column.links) ?? [];
    return <motion.div id={mobile ? `${id}-mobile` : id} className={mobile ? "art:absolute art:inset-x-0 art:top-[4.125rem] art:z-20 art:h-[27.125rem] art:overflow-hidden art:pt-2 art:@min-[768px]/artemis:hidden" : "art:absolute art:inset-x-0 art:top-[4.125rem] art:z-20 art:hidden art:h-[21.75rem] art:overflow-hidden art:pt-2 art:@min-[768px]/artemis:block"} initial={{ clipPath: "inset(0px 0px 100%)" }} animate={{ clipPath: "inset(0px 0px 0%)" }} exit={{ clipPath: "inset(0px 0px 100%)" }} transition={reduced ? { duration: 0 } : ARTEMIS_SPRING_PANEL}>
    <motion.span aria-hidden="true" className="art:absolute art:inset-x-0 art:top-0 art:h-px art:bg-border/60" initial={{ opacity: 0 }} animate={{ opacity: 1, transition: { duration: 0.15, ease: ARTEMIS_EASE_OUT, delay: 0.06 } }} exit={{ opacity: 0, transition: { duration: 0.08, ease: ARTEMIS_EASE_OUT } }}/>
    {mobile && <div className="art:flex art:gap-1 art:px-1">
      {menus.map((item, value) => <motion.button {...press} key={item.label} type="button" className={`art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:p-0 art:hover:bg-transparent art:hover:text-inherit art:min-h-10 art:px-3 art:font-medium art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-foreground/30 ${group === value ? "art:bg-muted art:text-foreground" : "art:text-muted-foreground"} art:rounded-full`} tabIndex={0} onClick={() => choose(value)}>{item.label}</motion.button>)}
      {links.map(link => <a key={link.label} href={link.href} onClick={close} className="art:flex art:min-h-10 art:items-center art:rounded-full art:px-3 art:font-medium art:text-muted-foreground art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-foreground/30">{link.label}</a>)}
    </div>}
    <AnimatePresence propagate>
      <motion.div key={group} className={mobile ? "art:absolute art:inset-x-0 art:grid art:grid-cols-2 art:gap-2 art:p-1 art:pt-2 art:top-12" : "art:absolute art:inset-x-0 art:top-0 art:grid art:grid-cols-2 art:gap-2 art:p-1 art:pt-2"}>
        {cards.map((card, index) => { const Icon = card.icon ?? icons[(group * 4 + index) % icons.length]; return <motion.a key={card.href} href={card.href} onClick={close} className="art:flex art:min-h-36 art:flex-col art:items-center art:justify-center art:rounded-3xl art:bg-background art:px-3 art:py-5 art:text-center art:outline-none art:transition-colors art:hover:bg-background/80 art:focus-visible:ring-2 art:focus-visible:ring-foreground/30 art:@min-[640px]/artemis:min-h-40 art:@min-[640px]/artemis:px-5 art:@min-[640px]/artemis:py-6" initial={{ opacity: 0, transform: `translateX(${reduced || mobile ? 0 : direction * 10}px) translateY(${reduced ? 0 : !mobile && direction ? 3 : 8}px)`, filter: reduced ? "blur(0px)" : "blur(4px)" }} animate={{ opacity: 1, transform: "translateX(0px) translateY(0px)", filter: "blur(0px)", transition: { duration: reduced ? 0.1 : 0.18, ease: ARTEMIS_EASE_OUT, delay: reduced ? 0 : 0.06 + index * 0.03 } }} exit={{ opacity: 0, ...(mobile ? { transform: `translateX(0px) translateY(${reduced ? 0 : -5}px)` } : {}), filter: reduced ? "blur(0px)" : "blur(2px)", transition: { duration: reduced ? 0.1 : 0.18, ease: ARTEMIS_EASE_OUT, delay: reduced ? 0 : (3 - index) * 0.03 } }}>
          <span className="art:grid art:size-11 art:place-items-center art:rounded-full art:border art:border-border art:bg-background art:text-foreground"><Icon className="art:size-5"/></span>
          <span className="art:mt-3 art:font-semibold art:text-base art:text-foreground art:@min-[640px]/artemis:text-lg">{card.label}</span>
          {card.description ? <span className="art:mt-1 art:text-muted-foreground art:text-xs art:@min-[640px]/artemis:text-sm">{card.description}</span> : null}
        </motion.a>; })}
      </motion.div>
    </AnimatePresence>
    {mobile && <div className="art:absolute art:inset-x-0 art:bottom-0 art:grid art:grid-cols-2 art:gap-2 art:p-1 art:pt-2">
      <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={login.href} tabIndex={0}>{login.label}</motion.a>
      <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={cta.href} tabIndex={0}>{cta.label}</motion.a>
    </div>}
  </motion.div>;
}
